declare(strict_types=1);namespace App\Services;use App\Core\Logger;final class MailService{public function sendOtp(string $to,string $code,int $minutes):void{if(MAIL_MODE==='log'){$line='['.date('Y-m-d H:i:s')."] OTP {$to}: {$code} (vence {$minutes} min)".PHP_EOL;file_put_contents(STORAGE_PATH.'/logs/mail.log',$line,FILE_APPEND|LOCK_EX);return;}require_once APP_ROOT.'/vendor/phpmailer/phpmailer/src/Exception.php';require_once APP_ROOT.'/vendor/phpmailer/phpmailer/src/SMTP.php';require_once APP_ROOT.'/vendor/phpmailer/phpmailer/src/PHPMailer.php';$m=new \PHPMailer\PHPMailer\PHPMailer(true);try{$m->isSMTP();$m->Host=SMTP_HOST;$m->Port=SMTP_PORT;$m->SMTPAuth=true;$m->Username=SMTP_USERNAME;$m->Password=SMTP_PASSWORD;$m->SMTPSecure=SMTP_SECURE;$m->CharSet='UTF-8';$m->setFrom(MAIL_FROM,MAIL_FROM_NAME);$m->addAddress($to);$m->isHTML(true);$m->Subject='Código de acceso | '.APP_NAME;$safe=htmlspecialchars($code,ENT_QUOTES,'UTF-8');$m->Body='<h2>Helpdesk Carrousel 360</h2><p>Tu código de acceso es:</p><p style="font-size:36px;font-weight:800;letter-spacing:8px">'.$safe.'</p><p>Vence en '.$minutes.' minutos.</p><p>No compartas este código.</p>';$m->AltBody="Tu código de acceso es {$code}. Vence en {$minutes} minutos.";$m->send();}catch(\Throwable $e){Logger::error($e);throw new \RuntimeException('No fue posible enviar el código OTP.');}}}
